1901	function handlePropertyResult(
1902	  result: ParsePayload,
1903	  final: ParsePayload,
1904	  key: PropertyKey,
1905	  input: any,
1906	  optin: "optional" | "defaulted" | undefined,
1907	  optout: "optional" | undefined
1908	) {
1909	  const isPresent = key in input;
1910	  const isOptionalOut = optout === "optional";
1911	  // The middle rung means "absence permitted, nothing supplied in its place", so an absent key contributes nothing — whatever the schema made of `undefined` is invented, not substituted. Only `optional` reaches this with a value: `defaulted` substitutes, and a schema that isn't optional-out has to keep the key.
1912	  if (!isPresent && isOptionalOut && optin === "optional") {
1913	    return;
1914	  }
1915	  if (result.issues.length) {
1916	    // For optional-in/out schemas, ignore errors on absent keys.
1917	    if (optin !== undefined && isOptionalOut && !isPresent) {
1918	      return;
1919	    }
1920	    final.issues.push(...util.prefixIssues(key, result.issues));
1921	  }
1922	
1923	  if (!isPresent && optin === undefined) {
1924	    if (!result.issues.length) {
1925	      final.issues.push({
1926	        code: "invalid_type",
1927	        expected: "nonoptional",
1928	        input: undefined,
1929	        path: [key],
1930	      });
1931	    }
1932	    return;
1933	  }
1934	
1935	  if (result.value === undefined) {
1936	    if (isPresent) {
1937	      (final.value as any)[key] = undefined;
1938	    }
1939	  } else {
1940	    (final.value as any)[key] = result.value;
1941	  }
1942	}
