import { expect, test } from "vitest";
import * as z from "zod/v4";
test("r", () => {
  let n = 0;
  const s = z.object({
    a: z.string().default(() => {
      n++;
      return "d";
    }),
  });
  s.parse({});
  expect(n).toBe(1);
  s.parse({});
  expect(n).toBe(2);
});

